# ===== MODULE: mechanics =====
"""Elementary Euler-Bernoulli beam models. Loads are characteristic/service loads, not ULS combinations."""
from dataclasses import dataclass
import numpy as np

@dataclass(frozen=True)
class Beam:
 span_m:float
 width_m:float
 depth_m:float
 e_gpa:float=30.0
 udl_kn_m:float=15.0
 point_kn:float=0.0
 point_x_m:float=0.0
 support:str="Simplement appuyée"

 def validate(self):
  if not 0.2<=self.span_m<=40:raise ValueError("Portée entre 0,2 et 40 m.")
  if not 0.05<=self.width_m<=3 or not 0.08<=self.depth_m<=4:raise ValueError("Dimensions de section hors limites.")
  if not 1<=self.e_gpa<=250:raise ValueError("Module E hors limites.")
  if not 0<=self.udl_kn_m<=500 or not 0<=self.point_kn<=10000:raise ValueError("Charges hors limites.")
  if not 0<=self.point_x_m<=self.span_m:raise ValueError("Position de charge hors portée.")
  if self.support not in ("Simplement appuyée","Console"):raise ValueError("Type d'appui inconnu.")

def analyze(b,n=401):
 b.validate()
 L=b.span_m;q=b.udl_kn_m;P=b.point_kn;a=b.point_x_m
 x=np.linspace(0,L,n);I=b.width_m*b.depth_m**3/12
 EI=b.e_gpa*1e6*I # kN/m² * m4 -> kN m²
 if b.support=="Simplement appuyée":
  rb=q*L/2+P*a/L;ra=q*L+P-rb
  V=ra-q*x-P*(x>=a)
  M=ra*x-q*x*x/2-P*np.maximum(x-a,0)
  # EIy = ra*x^3/6 - q*x^4/24 - P*<x-a>^3/6 + C1*x, C1 from y(L)=0
  c1=-(ra*L**3/6-q*L**4/24-P*(L-a)**3/6)/L
  y=(ra*x**3/6-q*x**4/24-P*np.maximum(x-a,0)**3/6+c1*x)/EI
  reactions={"RA":float(ra),"RB":float(rb)}
 else:
  # Console clamped x=0, free at x=L
  ra=q*L+P
  V=ra-q*x-P*(x>=a)
  M=-(q*(L-x)**2/2+P*np.maximum(a-x,0))
  # displacement from integrating M/EI twice, zero at x=0
  y=-(q*x*x*(6*L*L-4*L*x+x*x)/24 + P*(x*x*(3*a-x)/6)*(x<=a)
      +P*(a*a*(3*x-a)/6)*(x>a))/EI
  reactions={"RA":float(ra),"M_encastrement":float(q*L*L/2+P*a)}
 return {"x":x,"V":V,"M":M,"y_mm":y*1000,"inertia_m4":I,"volume_m3":b.width_m*b.depth_m*L,
         "m_max":float(np.max(np.abs(M))),"v_max":float(max(abs(V.min()),abs(V.max()))),
         "deflection_mm":float(np.max(np.abs(y))*1000),"reactions":reactions}
def rectangular_section_modulus(b,h):
 if b<=0 or h<=0:raise ValueError("Dimensions positives requises.")
 return b*h*h/6


# ===== MODULE: foundations =====
"""Centered footing sizing under a vertical service load; simplified bearing-pressure check only."""
import math
def centered_footing(load_kn,allowable_kpa,ratio=1.0,footing_depth_m=0.45,unit_weight_kn_m3=24.0,include_self_weight=True):
 if not 0<load_kn<=1e7 or not 1<=allowable_kpa<=5000 or not .3<=ratio<=4:raise ValueError("Charge, portance ou ratio hors limites.")
 if not .1<=footing_depth_m<=3 or not 10<=unit_weight_kn_m3<=40:raise ValueError("Épaisseur ou poids volumique hors limites.")
 net=allowable_kpa-(unit_weight_kn_m3*footing_depth_m if include_self_weight else 0)
 if net<=0:raise ValueError("Portance insuffisante après prise en compte du poids propre.")
 area=load_kn/net
 width=math.sqrt(area/ratio);length=width*ratio
 actual=(load_kn+unit_weight_kn_m3*footing_depth_m*area if include_self_weight else load_kn)/area
 return {"area_m2":area,"width_m":width,"length_m":length,"bearing_kpa":actual,"allowable_kpa":allowable_kpa}


# ===== MODULE: reliability =====
"""Illustrative probability of exceeding an explicit mechanical threshold, NOT code reliability."""
import numpy as np
def sample_udl_limit(beam,threshold_knm,cv=0.15,n=10000,seed=42):
 beam.validate()
 if beam.point_kn:raise ValueError("Simulation disponible uniquement pour une charge répartie (P=0).")
 if not 0<=cv<=1 or not 100<=n<=100000 or threshold_knm<=0:raise ValueError("Paramètres de simulation invalides.")
 rng=np.random.default_rng(int(seed))
 # Positive lognormal, mean = specified characteristic input for this teaching model
 sig=np.sqrt(np.log1p(cv*cv));mu=np.log(max(beam.udl_kn_m,1e-9))-sig*sig/2
 q=rng.lognormal(mu,sig,n)
 m=q*beam.span_m**2/(8 if beam.support=="Simplement appuyée" else 2)
 p=float(np.mean(m>threshold_knm))
 return {"moments":m,"probability":p,"mc_se":float(np.sqrt(p*(1-p)/n)),"p95":float(np.quantile(m,.95))}


# ===== MODULE: optimization =====
"""Educational serviceability screening; NOT normative reinforced-concrete sizing."""
def search(base,widths,depths,deflection_limit_mm,moment_limit_knm):
 if deflection_limit_mm<=0 or moment_limit_knm<=0:raise ValueError("Limites strictement positives.")
 rows=[]
 for width in widths:
  for depth in depths:
   try:
    b=Beam(base.span_m,float(width),float(depth),base.e_gpa,base.udl_kn_m,base.point_kn,base.point_x_m,base.support)
    a=analyze(b)
    # Moment resistance threshold is externally provided, not derived from dimensions.
    ok=a["deflection_mm"]<=deflection_limit_mm and a["m_max"]<=moment_limit_knm
    rows.append({"largeur_cm":round(width*100,1),"hauteur_cm":round(depth*100,1),
                 "volume_m3":round(a["volume_m3"],4),"fleche_mm":round(a["deflection_mm"],3),
                 "moment_knm":round(a["m_max"],3),"admissible_selon_criteres_saisis":ok})
   except ValueError:pass
 return sorted(rows,key=lambda x:x["volume_m3"])


# ===== MODULE: reports =====
import io
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.lib import colors
def pdf(title,inputs,outputs,warning):
 buf=io.BytesIO();styles=getSampleStyleSheet()
 story=[Paragraph("DIMENSIA | NOTE DE CALCUL PÉDAGOGIQUE",styles["Title"]),Spacer(1,12),Paragraph(title,styles["Heading2"])]
 for label,items in (("Hypothèses et données",inputs),("Résultats",outputs)):
  story.append(Spacer(1,14));story.append(Paragraph(label,styles["Heading3"]))
  rows=[["Paramètre","Valeur"]]+[[str(k),str(v)] for k,v in items.items()]
  t=Table(rows,colWidths=[240,270],repeatRows=1)
  t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#183A54")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("GRID",(0,0),(-1,-1),.3,colors.lightgrey),("TOPPADDING",(0,0),(-1,-1),7),("BOTTOMPADDING",(0,0),(-1,-1),7)]))
  story.append(t)
 story.extend([Spacer(1,20),Paragraph(warning,styles["Italic"])])
 SimpleDocTemplate(buf,pagesize=(595,842),leftMargin=42,rightMargin=42).build(story)
 return buf.getvalue()


# ===== MODULE: datasets =====
"""Transparent exploratory analysis of imported engineering observations.

No model is trained and no fabricated dataset is presented as field measurements.
"""
from pathlib import Path
import io
import numpy as np
import pandas as pd

MAX_BYTES = 12 * 1024 * 1024
MAX_ROWS = 200_000

def load_table(content: bytes, filename: str) -> pd.DataFrame:
    if not content or len(content) > MAX_BYTES:
        raise ValueError('Fichier vide ou supérieur à 12 Mo.')
    suffix = Path(filename).suffix.lower()
    if suffix == '.csv':
        try:
            df = pd.read_csv(io.BytesIO(content), sep=None, engine='python')
        except UnicodeDecodeError:
            df = pd.read_csv(io.BytesIO(content), sep=None, engine='python', encoding='latin-1')
    elif suffix == '.xlsx':
        df = pd.read_excel(io.BytesIO(content), engine='openpyxl')
    else:
        raise ValueError('Seuls les fichiers CSV et XLSX sont acceptés.')
    if len(df) > MAX_ROWS or len(df.columns) > 150:
        raise ValueError('Limite : 200 000 lignes et 150 colonnes.')
    if df.empty:
        raise ValueError('Le tableau ne contient aucune observation.')
    return df

def audit(df: pd.DataFrame) -> pd.DataFrame:
    return pd.DataFrame({
        'variable': [str(c) for c in df.columns],
        'type': [str(df[c].dtype) for c in df.columns],
        'effectif': [int(df[c].notna().sum()) for c in df.columns],
        'manquants': [int(df[c].isna().sum()) for c in df.columns],
        'manquants_pct': [round(float(df[c].isna().mean() * 100), 2) for c in df.columns],
        'uniques': [int(df[c].nunique(dropna=True)) for c in df.columns]
    })

def numeric_stats(df: pd.DataFrame) -> pd.DataFrame:
    numeric = df.select_dtypes(include='number').replace([np.inf, -np.inf], np.nan)
    if numeric.empty:
        return pd.DataFrame()
    d = numeric.describe(percentiles=[.05, .25, .5, .75, .95]).T
    d['missing'] = numeric.isna().sum()
    d['cv'] = (d['std'] / d['mean'].abs().replace(0, np.nan))
    return d

def linear_fit(df: pd.DataFrame, x: str, y: str):
    if x == y:
        raise ValueError('Choisissez deux variables différentes.')
    pair = df[[x,y]].apply(pd.to_numeric, errors='coerce').replace([np.inf, -np.inf], np.nan).dropna()
    if len(pair) < 4 or pair[x].nunique() < 2:
        raise ValueError('Au moins quatre couples complets et deux valeurs X distinctes sont requis.')
    a,b = np.polyfit(pair[x].to_numpy(float), pair[y].to_numpy(float), 1)
    pred = a * pair[x].to_numpy(float) + b
    ss_res = float(np.sum((pair[y].to_numpy(float)-pred)**2))
    ss_tot = float(np.sum((pair[y].to_numpy(float)-pair[y].mean())**2))
    r2 = 1 - ss_res/ss_tot if ss_tot else float('nan')
    return {'pente':float(a), 'interception':float(b), 'r2':r2, 'n':len(pair)}, pair


# ===== MODULE: loads =====
"""User-defined combination of permanent and variable loads.

Factors are not claimed to represent BAEL or EC2 normative coefficients.
"""
from dataclasses import dataclass

@dataclass(frozen=True)
class LoadCombination:
    permanent_kn_m: float
    variable_kn_m: float
    gamma_g: float
    gamma_q: float

    def evaluate(self):
        values=(self.permanent_kn_m,self.variable_kn_m,self.gamma_g,self.gamma_q)
        if any(v<0 or v>10000 for v in values):
            raise ValueError('Charges et coefficients entre 0 et 10 000.')
        return {
            'G (kN/m)': self.permanent_kn_m,
            'Q (kN/m)': self.variable_kn_m,
            'gamma_G': self.gamma_g,
            'gamma_Q': self.gamma_q,
            'q_combine (kN/m)': self.gamma_g*self.permanent_kn_m+self.gamma_q*self.variable_kn_m,
        }


# ===== MODULE: sections =====
"""Geometric section properties; pure geometry, not reinforced concrete design."""
import math

def rectangle(b,h):
    if b<=0 or h<=0: raise ValueError('Dimensions positives requises.')
    return {'aire_m2':b*h,'ix_m4':b*h**3/12,'iy_m4':h*b**3/12,
            'wx_m3':b*h*h/6,'wy_m3':h*b*b/6,'rayon_giration_x_m':h/math.sqrt(12)}

def circle(d):
    if d<=0: raise ValueError('Diamètre positif requis.')
    return {'aire_m2':math.pi*d*d/4,'ix_m4':math.pi*d**4/64,
            'wx_m3':math.pi*d**3/32,'rayon_giration_m':d/4}

def hollow_rectangle(b,h,bi,hi):
    if not 0<bi<b or not 0<hi<h:raise ValueError('Dimensions intérieures inférieures aux extérieures.')
    area=b*h-bi*hi
    ix=(b*h**3-bi*hi**3)/12
    iy=(h*b**3-hi*bi**3)/12
    return {'aire_m2':area,'ix_m4':ix,'iy_m4':iy,'wx_m3':2*ix/h,'wy_m3':2*iy/b}



